from src.stockflow.first_fit_decreasing import first_fit_decreasing

def split_shipment(lines: Sequence[Tuple[str, int, int]], max_parcel_grams: int) -> List[Dict[str, int]]:
    if max_parcel_grams <= 0: raise ValueError()
    mw, mq = {}, {}
    for s, q, w in lines:
        if q <= 0 or w <= 0: raise ValueError()
        if s in mw and mw[s] != w: raise ValueError()
        mw[s], mq[s] = w, mq.get(s, 0) + q
    items = []
    for s, q in mq.items():
        w = mw[s]
        if w > max_parcel_grams: raise ValueError()
        u = max_parcel_grams // w
        for _ in range(q // u): items.append((s, u * w))
        if q % u: items.append((s, (q % u) * w))
    bins = first_fit_decreasing(items, max_parcel_grams)
    res = []
    for b in bins:
        p = {}
        for s, bw in b: p[s] = p.get(s, 0) + (bw // mw[s])
        res.append(p)
    return res"}}}
